package lifecycle

import (
 "context"
 "crypto/sha256"
 "encoding/hex"
 "database/sql"
 "io"
 "os"
 "path/filepath"
 "sort"
 "strings"
 "nice-wiki/libs/platform"
)

type snapshotCaptureKey struct{}
// Exclude只由owner启动装配的明确私有相对路径组成；不接受请求自报或glob。
type SnapshotCaptureExclude struct{Paths []string}
// CaptureSnapshotFiles只在Manager真实safe Capture回调内执行；业务库存仍由本域实际记录产生。
func CaptureSnapshotFiles(ctx context.Context,activeRoot,workspace string,databases map[string]*sql.DB,exclude SnapshotCaptureExclude)([]DomainSnapshotFile,error){
 manager,ok:=ctx.Value(snapshotCaptureKey{}).(*SnapshotManager);if !ok||filepath.Clean(activeRoot)!=filepath.Join(manager.config.DataRoot,"active"){return nil,platform.NewError(platform.CodeLocked,false,"完整捕获缺真实安全截点与active根绑定")};manager.mu.Lock();safe:=manager.fileOps>0&&manager.record!=nil&&manager.record.Status.State=="safe";manager.mu.Unlock();if !safe{return nil,platform.NewError(platform.CodeLocked,true,"完整捕获安全截点已失效")};if err:=ValidatePrivatePath(activeRoot,"directory",false);err!=nil{return nil,err};root:=filepath.Join(workspace,"files");if err:=ValidatePrivatePath(root,"directory",false);err!=nil{return nil,err};relative,err:=filepath.Rel(activeRoot,root);if err!=nil||relative=="."||(!strings.HasPrefix(relative,".."+string(filepath.Separator))&&relative!=".."){return nil,integrity("捕获workspace不能位于active内部")};entries,err:=os.ReadDir(root);if err!=nil{return nil,snapshotIOError(err)};if len(entries)!=0{return nil,integrity("完整捕获workspace不是空树")}
 excludes:=map[string]bool{};for _,path:=range exclude.Paths{if !safeSnapshotRelative(path)||excludes[path]{return nil,integrity("固定捕获排除策略不合法")};excludes[path]=true};isExcluded:=func(path string)bool{for prefix:=range excludes{if path==prefix||strings.HasPrefix(path,prefix+"/"){return true}};return false}
 files:=[]DomainSnapshotFile{};directories:=[]string{};registered:=map[string]bool{};names:=make([]string,0,len(databases));for path,db:=range databases{if db==nil||!safeSnapshotRelative(path)||isExcluded(path){return nil,integrity("登记SQLite路径、连接或排除策略矛盾")};registered[path]=true;names=append(names,path)};sort.Strings(names)
 var planned int64;var plannedFiles int
 if err=filepath.WalkDir(activeRoot,func(path string,entry os.DirEntry,walkErr error)error{if walkErr!=nil{return snapshotIOError(walkErr)};relative,err:=filepath.Rel(activeRoot,path);if err!=nil{return snapshotIOError(err)};if relative=="."{return nil};relative=filepath.ToSlash(relative);kind:="regular-file";if entry.IsDir(){kind="directory"};if err=ValidatePrivatePath(path,kind,false);err!=nil{return err};if isExcluded(relative){if entry.IsDir(){return filepath.SkipDir};return nil};if entry.IsDir(){return nil};if strings.HasSuffix(relative,"-wal")&&registered[strings.TrimSuffix(relative,"-wal")]||strings.HasSuffix(relative,"-shm")&&registered[strings.TrimSuffix(relative,"-shm")]{return nil};info,err:=entry.Info();if err!=nil{return snapshotIOError(err)};if info.Size()>MaxArchiveBytes-planned{return snapshotBudget("完整active捕获超过20GiB")};planned+=info.Size();plannedFiles++;if plannedFiles+1>MaxArchiveFiles{return snapshotBudget("active捕获文件数超过归档上界")};return nil});err!=nil{return nil,err};if err=CheckSnapshotDiskBudget(ctx,workspace,planned);err!=nil{return nil,err}
 for _,path:=range names{db:=databases[path];source:=filepath.Join(activeRoot,filepath.FromSlash(path));if err=ValidatePrivatePath(source,"regular-file",false);err!=nil{return nil,err};rows,queryErr:=db.QueryContext(ctx,"PRAGMA database_list");if queryErr!=nil{return nil,snapshotIOError(queryErr)};found:=false;for rows.Next(){var sequence int;var name,file string;if err=rows.Scan(&sequence,&name,&file);err!=nil{_ = rows.Close();return nil,snapshotIOError(err)};if name=="main"{actual,absoluteErr:=filepath.Abs(file);if absoluteErr!=nil||filepath.Clean(actual)!=filepath.Clean(source){_ = rows.Close();return nil,integrity("SQLite连接不属于登记active文件")};found=true}};err=rows.Err();_ = rows.Close();if err!=nil{return nil,snapshotIOError(err)};if !found{return nil,integrity("SQLite主数据库归属未知")};destination:=filepath.Join(root,filepath.FromSlash(path));if err=snapshotDirectory(filepath.Dir(destination),manager.config.DataRoot);err!=nil{return nil,err};if _,err=db.ExecContext(ctx,"VACUUM main INTO ?",destination);err!=nil{return nil,snapshotIOError(err)};if err=os.Chmod(destination,0600);err!=nil{return nil,snapshotIOError(err)};copied,openErr:=os.Open(destination);if openErr!=nil{return nil,snapshotIOError(openErr)};info,statErr:=copied.Stat();if statErr!=nil{_ = copied.Close();return nil,snapshotIOError(statErr)};digest:=sha256.New();_,copyErr:=io.Copy(digest,io.LimitReader(copied,MaxArchiveBytes+1));if copyErr==nil{copyErr=copied.Sync()};_ = copied.Close();if copyErr!=nil{return nil,snapshotIOError(copyErr)};if info.Size()>MaxArchiveBytes{return nil,snapshotBudget("SQLite一致副本超过完整上界")};files=append(files,DomainSnapshotFile{Path:path,SHA256:hex.EncodeToString(digest.Sum(nil)),ByteSize:info.Size()})}
 err=filepath.WalkDir(activeRoot,func(source string,entry os.DirEntry,walkErr error)error{
 if walkErr!=nil{return snapshotIOError(walkErr)};if err:=ctx.Err();err!=nil{return snapshotIOError(err)};relative,err:=filepath.Rel(activeRoot,source);if err!=nil{return snapshotIOError(err)};if relative=="."{return nil};path:=filepath.ToSlash(relative);if !safeSnapshotRelative(path){return integrity("active树路径不合法")};kind:="regular-file";if entry.IsDir(){kind="directory"};if err=ValidatePrivatePath(source,kind,false);err!=nil{return err};if isExcluded(path){if entry.IsDir(){return filepath.SkipDir};return nil};if entry.IsDir(){directories=append(directories,path);return snapshotDirectory(filepath.Join(root,relative),manager.config.DataRoot)};if registered[path]||registered[strings.TrimSuffix(path,"-wal")]&&strings.HasSuffix(path,"-wal")||registered[strings.TrimSuffix(path,"-shm")]&&strings.HasSuffix(path,"-shm"){return nil};if strings.HasSuffix(path,"-journal")&&registered[strings.TrimSuffix(path,"-journal")]{return platform.NewError(platform.CodeLocked,true,"SQLite回滚journal尚未结束，不能捕获不明事务")};sourceFile,err:=os.Open(source);if err!=nil{return snapshotIOError(err)};defer sourceFile.Close();prefix:=make([]byte,16);n,readErr:=io.ReadFull(sourceFile,prefix);if readErr!=nil&&readErr!=io.ErrUnexpectedEOF&&readErr!=io.EOF{return snapshotIOError(readErr)};if n==16&&string(prefix)=="SQLite format 3\x00"{return integrity("active存在未登记live SQLite，禁止原样复制")};if _,err=sourceFile.Seek(0,io.SeekStart);err!=nil{return snapshotIOError(err)};info,err:=sourceFile.Stat();if err!=nil{return snapshotIOError(err)};if info.Size()>MaxArchiveBytes{return snapshotBudget("active文件超过完整归档上界")};destination:=filepath.Join(root,relative);if err=snapshotDirectory(filepath.Dir(destination),manager.config.DataRoot);err!=nil{return err};target,err:=os.OpenFile(destination,os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if err!=nil{return snapshotIOError(err)};digest:=sha256.New();_,copyErr:=io.CopyN(io.MultiWriter(target,digest),sourceFile,info.Size());if copyErr==nil{var extra [1]byte;if count,endErr:=sourceFile.Read(extra[:]);count!=0||endErr!=io.EOF{copyErr=integrity("捕获期间源文件长度改变")}};if copyErr==nil{copyErr=target.Sync()};closeErr:=target.Close();if copyErr!=nil{return snapshotIOError(copyErr)};if closeErr!=nil{return snapshotIOError(closeErr)};files=append(files,DomainSnapshotFile{Path:path,SHA256:hex.EncodeToString(digest.Sum(nil)),ByteSize:info.Size()});return nil
 });if err!=nil{return nil,err}
 sort.Slice(files,func(i,j int)bool{return files[i].Path<files[j].Path});sort.Strings(directories);var total int64;for _,file:=range files{if file.ByteSize>MaxArchiveBytes-total{return nil,snapshotBudget("完整捕获文件超过上界")};total+=file.ByteSize};for i:=len(directories)-1;i>=0;i--{if err=syncSnapshotDirectories(filepath.Join(root,filepath.FromSlash(directories[i])),manager.config.DataRoot);err!=nil{return nil,err}};if err=syncSnapshotDirectories(root,manager.config.DataRoot);err!=nil{return nil,err};return files,nil
}
